26	function StaleBanner() {
27	  const { workspaceDetail, syncBoard, syncing } = useBoardContext();
28	  const { source_state } = workspaceDetail;
29	  if (!source_state?.stale) return null;
30	
31	  return (
32	    <div
33	      role="alert"
34	      aria-live="polite"
35	      className="flex items-center gap-3 border-b border-warning/30 bg-warning/10 px-4 py-2"
36	    >
37	      <AlertTriangle className="h-4 w-4 shrink-0 text-warning" aria-hidden="true" />
38	      <p className="flex-1 text-xs text-warning">
39	        <span className="font-semibold">Stale data</span>
40	        {source_state.error_code ? ` — ${source_state.error_code}` : " — workspace data may be out of date."}
41	      </p>
42	      <button
43	        type="button"
44	        onClick={syncBoard}
45	        disabled={syncing}
46	        aria-label="Sync workspace to refresh data"
47	        className="flex items-center gap-1.5 rounded border border-warning/40 bg-warning/10 px-2 py-0.5 text-[11px] font-medium text-warning transition-colors hover:bg-warning/20 disabled:cursor-not-allowed disabled:opacity-50"
48	      >
49	        <RefreshCw
50	          className={"h-3 w-3 " + (syncing ? "animate-spin" : "")}
51	          aria-hidden="true"
52	        />
53	        {syncing ? "Syncing…" : "Sync now"}
54	      </button>
55	    </div>
56	  );
57	}
58	
59	function ModeSegmentedControl() {
60	  const { boardMode, setBoardMode } = useBoardContext();
61	
62	  function handleModeClick(mode: BoardMode) {
63	    if (mode !== boardMode) {
64	      setBoardMode(mode);
65	    }
66	  }
67	
68	  return (
69	    <div
70	      className="inline-flex items-stretch rounded-md border border-border bg-surface p-0.5 shadow-sm"
71	      role="tablist"
72	      aria-label="Board mode"
73	    >
74	      <button
75	        type="button"
76	        role="tab"
77	        aria-selected={boardMode === "task"}
78	        onClick={() => handleModeClick("task")}
79	        className={
80	          "flex h-7 items-center gap-1.5 rounded-sm px-3 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-surface " +
81	          (boardMode === "task"
82	            ? "border border-success bg-success text-white shadow-sm"
83	            : "border border-transparent text-text-secondary hover:bg-surface-subtle hover:text-text-primary")
84	        }
85	      >
86	        <ListChecks className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
87	        Task
88	      </button>
89	      <button
90	        type="button"
91	        role="tab"
92	        aria-selected={boardMode === "feature"}
93	        onClick={() => handleModeClick("feature")}
94	        className={
95	          "flex h-7 items-center gap-1.5 rounded-sm px-3 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-surface " +
96	          (boardMode === "feature"
97	            ? "border border-success bg-success text-white shadow-sm"
98	            : "border border-transparent text-text-secondary hover:bg-surface-subtle hover:text-text-primary")
99	        }
100	      >
101	        <LayoutGrid className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
102	        Feature
103	      </button>
104	    </div>
105	  );
106	}
107	
108	function TaskModeFilterMenu({ onClose }: { onClose: () => void }) {
109	  const { taskActiveFilters, setTaskActiveFilters } = useBoardContext();
110	  const selectedStatuses = new Set(taskActiveFilters.statuses);
111	  const allSelected = isAllStatusFilterSelected(taskActiveFilters.statuses);
112	
113	  function toggleStatus(status: string) {
114	    setTaskActiveFilters({
115	      statuses: toggleStatusFilter(taskActiveFilters.statuses, status),
116	    });
117	  }
118	
119	  function toggleAll() {
120	    setTaskActiveFilters({
121	      statuses: toggleAllStatusFilter(taskActiveFilters.statuses),
122	    });
123	  }
124	
125	  return (
126	    <div
127	      role="menu"
128	      className="absolute right-0 top-9 z-30 w-48 border border-border bg-surface p-2 shadow-lg"
129	    >
130	      <label className="mb-1 flex cursor-pointer items-center gap-2 border-b border-border px-2 py-1.5 pb-2 text-xs font-semibold text-text-primary hover:bg-surface-subtle">
131	        <input
132	          type="checkbox"
133	          checked={allSelected}
134	          onChange={toggleAll}
135	          className="h-3 w-3 accent-primary"
136	        />
137	        All
138	      </label>
139	      {STATUS_COLUMNS.map((status) => (
140	        <label
141	          key={status.key}
142	          className="flex cursor-pointer items-center gap-2 px-2 py-1.5 text-xs text-text-secondary hover:bg-surface-subtle"
143	        >
144	          <input
145	            type="checkbox"
146	            checked={selectedStatuses.has(status.key)}
147	            onChange={() => toggleStatus(status.key)}
148	            className="h-3 w-3 accent-primary"
149	          />
150	          <span
151	            className="h-2 w-2 rounded-sm"
152	            style={{ background: status.color }}
153	            aria-hidden="true"
154	          />
155	          <span>{status.label}</span>
156	        </label>
